function useRanaSequence(count,delay){
 const [frame,setFrame]=React.useState(0),[paused,setPaused]=React.useState(()=>window.matchMedia('(prefers-reduced-motion: reduce)').matches),[visible,setVisible]=React.useState(false);const ref=React.useRef(null);
 React.useEffect(()=>{const o=new IntersectionObserver(([e])=>setVisible(e.isIntersecting),{threshold:.2});if(ref.current)o.observe(ref.current);return()=>o.disconnect();},[]);
 React.useEffect(()=>{if(paused||!visible)return;const t=setInterval(()=>{if(!document.hidden)setFrame(v=>(v+1)%count);},delay);return()=>clearInterval(t);},[paused,visible,count,delay]);
 return {frame,setFrame,paused,setPaused,ref,step:d=>{setPaused(true);setFrame(v=>(v+d+count)%count);}};
}
